SELECT pg_catalog.jsonb_build_object(
  'witness', 'DEC203_FINALITY_CAPABILITY_AUDIT_V1',
  'database', pg_catalog.current_database(),
  'databaseOid', (SELECT d.oid::pg_catalog.text
