  'observerPid', pg_catalog.pg_backend_pid(),
  'backends', COALESCE((
    SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'pid', a.pid,
      'databaseOid', a.datid::pg_catalog.text,
      'databaseName', a.datname,
